mapper.select:
WITH review_images AS ( SELECT ri.review_id, LISTAGG(ri.file_name, ',') WITHIN GROUP (ORDER BY ri.file_name) AS file_names FROM review_img ri GROUP BY ri.review_id ), review_likes AS ( SELECT r.review_id, COUNT(l.like_id) AS like_count FROM review r LEFT JOIN likes l ON r.review_id = l.review_id GROUP BY r.review_id ), review_comments AS ( SELECT review_id, COUNT(*) AS comment_count FROM comments GROUP BY review_id ), paginated_reviews AS ( SELECT r.review_id, r.review_title, r.review_regdate, r.review_cnt, m.member_nickname, COALESCE(ri.file_names, '') AS file_names, COALESCE(rl.like_count, 0) AS like_count, COALESCE(rc.comment_count, 0) AS comment_count, ROW_NUMBER() OVER (ORDER BY r.review_id DESC) AS rn FROM review r INNER JOIN member m ON r.member_email = m.member_email LEFT JOIN review_images ri ON r.review_id = ri.review_id LEFT JOIN review_likes rl ON r.review_id = rl.review_id LEFT JOIN review_comments rc ON r.review_id = rc.review_id
LOWER(${searchCondition}) LIKE '%' || LOWER(#{searchKeyword}) || '%'
) SELECT * FROM paginated_reviews WHERE rn BETWEEN #{offset} + 1 AND #{offset} + #{pageSize}

SELECT COUNT(*)
FROM COMMENTS
WHERE review_id = #{review_id}

mapper.update:
UPDATE member
SET member_review = member_review + 1
WHERE member_email = #{member_email}

UPDATE review SET
review_title = #{review_title},
review_content = #{review_content}
WHERE review_id = #{review_id}

UPDATE member
SET member_review = member_review - 1
WHERE member_email = #{member_email}

UPDATE review
SET review_cnt = review_cnt + 1
WHERE review_id = #{review_id}
